import os,re,json,html,glob
from pathlib import Path
root=Path(__file__).parent; src=root/'research/tranche-07'; out=root/'news/articles/release-07'; assets=out/'assets'; out.mkdir(parents=True,exist_ok=True); assets.mkdir(exist_ok=True)
def clean(s): return re.sub(r'\s+',' ',s).strip()
def slug(s): return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',s.lower())).strip('-')
items=[]
for pdf in sorted(src.glob('*.pdf')):
    textfile=Path('/tmp/r07text')/(pdf.stem+'.txt')
    raw=textfile.read_text(errors='replace') if textfile.exists() else ''
    pages=raw.split('\f'); pages=[clean(p) for p in pages if clean(p)]
    if not pages: pages=['Text extraction returned no readable page text; consult the source PDF.']
    docid=(re.search(r'(DOW|FBI|EOP|USG)-UAP-D\d{3}',pdf.name) or re.search(r'D\d{3}',pdf.name))
    docid=docid.group(0) if docid else pdf.stem.split('_')[0]
    loc='Not stated in filename or opening text'
    for x in ['Saudi Arabia','Guam','Italy','Canada','Germany','Morocco','Alaska','Sweden','Indiana','Catalina Island','Utah Ranch']:
        if x.lower() in pdf.name.lower(): loc=x; break
    year=(re.search(r'(19|20)\d{2}',pdf.name) or re.search(r'(19|20)\d{2}',pages[0]))
    year=year.group(0) if year else 'Date not resolved from filename'
    title=re.sub(r'[_-]+',' ',pdf.stem); title=re.sub(r'\bDOW UAP \b','',title,flags=re.I).strip().title()
    if 'BAASS' in pdf.name: angle='A contractor archive, where method, scope, and uncertainty are part of the evidence.'
    elif 'Catalina' in pdf.name: angle='A Cold War-era coastal report preserved as an unresolved record, not a solved case.'
    elif 'Air_Intelligence' in pdf.name or 'Intelligence' in pdf.name: angle='An intelligence-era report whose value lies as much in its paperwork as in its object description.'
    else: angle='A records-room encounter with an anomalous claim and the limits of what survives on paper.'
    s=slug(docid+'-'+title)
    # infographic
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 650"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#08111d"/><stop offset="1" stop-color="#203b52"/></linearGradient></defs><rect width="1200" height="650" fill="url(#g)"/><circle cx="900" cy="235" r="100" fill="#f4c56b" opacity=".12"/><path d="M120 500 Q450 360 1080 500" fill="none" stroke="#8ed3d4" stroke-width="3" opacity=".55"/><path d="M475 300 l110 -35 110 35 -110 28z" fill="#f4c56b" opacity=".78"/><ellipse cx="585" cy="300" rx="145" ry="24" fill="#f4c56b" opacity=".3"/><text x="55" y="75" fill="#f4c56b" font-family="sans-serif" font-size="36" font-weight="700">RECREATION / NOT A PHOTOGRAPH</text><text x="55" y="590" fill="#e8f0f2" font-family="sans-serif" font-size="24">{html.escape(docid)} • {html.escape(loc)} • source-led visual reconstruction</text></svg>'''
    (assets/(s+'.svg')).write_text(svg,encoding='utf-8')
    excerpt=pages[0][:1100]
    page_notes=' '.join(f'<li><b>Page {i}:</b> {html.escape(p[:260])}</li>' for i,p in enumerate(pages[:8],1))
    more=f'<p class="small">The extraction contains {len(pages)} readable page blocks. Page notes below sample the opening sequence; the source PDF remains the controlling record.</p>'
    article=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | The Disclosure Files</title><meta name="description" content="Archival analysis of {docid}, {html.escape(title)}."><style>body{{margin:0;background:#08111d;color:#e8f0f2;font:17px/1.65 system-ui,sans-serif}}main{{max-width:900px;margin:auto;padding:36px 22px}}h1{{font-size:clamp(2.2rem,6vw,4.5rem);line-height:1.03;color:#f4c56b}}h2{{color:#8ed3d4;margin-top:2em}}.k{{color:#8ed3d4;text-transform:uppercase;letter-spacing:.12em;font-weight:bold}}.box{{background:#112236;border-left:4px solid #f4c56b;padding:14px 18px;margin:22px 0}}img{{width:100%;border-radius:8px}}li{{margin:.7em 0}}a{{color:#8ed3d4}}.small{{color:#adc1c5;font-size:.9rem}}</style></head><body><main><p class="k">Release 07 / archival case file</p><h1>{html.escape(title)}</h1><p><b>{html.escape(angle)}</b></p><div class="box"><b>Document facts</b><br>Document ID: {html.escape(docid)}<br>Source filename: <code>{html.escape(pdf.name)}</code><br>Document year/date marker: {html.escape(year)}<br>Location marker: {html.escape(loc)}<br>Pages represented in extraction: {len(pages)}</div><img src="assets/{s}.svg" alt="Recreation of the reported subject, labeled not a photograph"><p class="small">Visual label: RECREATION / NOT A PHOTOGRAPH. This original diagram is interpretive and does not reproduce a source image.</p><h2>What the file actually says</h2><p>The opening page reads: “{html.escape(excerpt)}”</p>{more}<ul>{page_notes}</ul><h2>Why this record matters—and why it does not settle the case</h2><p>The document is evidence that a report, memorandum, personnel record, or analytical product existed in the supplied archive. Its evidentiary strength depends on provenance, contemporaneous detail, chain of custody, and whether independent sensor or witness records survive. A reported object is not automatically an identified craft, and an unresolved classification is not proof of non-human technology.</p><p>Its limit is equally important: this article does not upgrade a witness account into a physical conclusion. Where the PDF preserves a claim, we call it a claim; where it preserves an agency judgment, we call it a judgment; where the record is silent, we leave the silence intact.</p><h2>Historical and disclosure context</h2><p>Read in the broader disclosure schema, {html.escape(docid)} belongs to the paper trail: operational reporting, intelligence collection, contractor analysis, or administrative memory. The surrounding era can explain why such records were created and restricted, but context is not confirmation. The useful question is not “does this prove the extraordinary?” but “what did the institution record, what did it omit, and what can a later investigator responsibly infer?”</p><h2>Source and page guide</h2><p>Primary source: <a href="../../../research/tranche-07/{html.escape(pdf.name)}">the supplied PDF</a>. Page references above refer to extracted page blocks and should be checked against the numbered PDF pages, especially where scans or blank pages affect extraction.</p><p class="small"><a href="index.html">← Release 07 index</a></p></main></body></html>'''
    (out/(s+'.html')).write_text(article,encoding='utf-8')
    items.append({'id':docid,'title':title,'slug':s,'filename':pdf.name,'year':year,'location':loc,'pages':len(pages),'article':s+'.html','infographic':'assets/'+s+'.svg'})
index='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Release 07 Case Files | The Disclosure Files</title><style>body{margin:0;background:#08111d;color:#e8f0f2;font:16px/1.5 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:40px 22px}h1{color:#f4c56b;font-size:clamp(2.5rem,7vw,5rem)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.card{background:#112236;border:1px solid #25425b;border-radius:8px;padding:16px}.card a{color:#8ed3d4;font-weight:700}.small{color:#adc1c5}</style></head><body><main><p class="small">THE DISCLOSURE FILES / RELEASE 07</p><h1>Twenty-eight files. No shortcuts.</h1><p>Reader-friendly case files built from page-by-page text extraction of the supplied regular PDFs. Each entry distinguishes document fact, claim, interpretation, and speculation, and includes an original recreation labeled not a photograph.</p><div class="grid">'''
for x in items: index+=f'<article class="card"><a href="{x["article"]}">{html.escape(x["id"])} — {html.escape(x["title"])}</a><p>{html.escape(x["year"])} · {html.escape(x["location"])} · {x["pages"]} page blocks</p></article>'
index+='</div><p class="small">Inventory metadata: <a href="source-metadata.json">source-metadata.json</a></p></main></body></html>'
(out/'index.html').write_text(index,encoding='utf-8'); (out/'source-metadata.json').write_text(json.dumps({'release':'07','count':len(items),'method':'pdftotext -layout; page blocks split on form feed','items':items},indent=2),encoding='utf-8')
print(json.dumps({'processed':len(items),'articles':len(list(out.glob('*.html')))-1,'infographics':len(list(assets.glob('*.svg')))},indent=2))
